import { useEffect, useState } from "react";

const RESET_GUARD_KEY = "solopti.selfrecovery.gerror-reset-at";
const RELOAD_GUARD_KEY = "solopti.selfrecovery.gerror-reload-at";
const GUARD_WINDOW_MS = 60000;

function withinWindow(key: string): boolean {
  try {
    const last = Number(window.sessionStorage.getItem(key) || 0);
    return Date.now() - last < GUARD_WINDOW_MS;
  } catch {
    return true;
  }
}

function markNow(key: string): void {
  try {
    window.sessionStorage.setItem(key, String(Date.now()));
  } catch {
    // 記録不可でも画面表示は継続
  }
}

/**
 * 全体エラー画面 (root layout 失敗時の最終防衛線)。
 * 非技術・日本語のみ。自動 reset() 1回 → ガード付き再読込1回 → 手動「再読み込み」ボタン。
 */
export default function GlobalRecoverableError({
  reset,
}: {
  error?: unknown;
  reset: () => void;
}) {
  const [autoRetrying, setAutoRetrying] = useState(true);

  useEffect(() => {
    if (!withinWindow(RESET_GUARD_KEY)) {
      markNow(RESET_GUARD_KEY);
      const t = window.setTimeout(() => reset(), 1200);
      return () => window.clearTimeout(t);
    }
    if (!withinWindow(RELOAD_GUARD_KEY)) {
      markNow(RELOAD_GUARD_KEY);
      const t = window.setTimeout(() => window.location.reload(), 1200);
      return () => window.clearTimeout(t);
    }
    setAutoRetrying(false);
    return undefined;
  }, [reset]);

  return (
    <html lang="ja">
      <body
        style={{
          margin: 0, minHeight: "100vh", display: "flex", flexDirection: "column",
          alignItems: "center", justifyContent: "center", gap: 20, padding: 24,
          background: "#f9fafb",
          fontFamily: "-apple-system,BlinkMacSystemFont,'Hiragino Sans','Noto Sans JP',sans-serif",
          textAlign: "center",
        }}
      >
        <style>{"@keyframes solopti-ger-spin{to{transform:rotate(360deg)}}"}</style>
        <div
          style={{
            width: 44, height: 44, borderRadius: 9999,
            border: "4px solid #e5e7eb", borderTopColor: "#0284c7",
            animation: "solopti-ger-spin 0.8s linear infinite",
          }}
        />
        <div style={{ fontSize: 16, fontWeight: 700, color: "#111827" }}>
          {autoRetrying
            ? "読み込みに時間がかかっています。自動で再試行しています…"
            : "読み込みに時間がかかっています。"}
        </div>
        <div style={{ fontSize: 13, color: "#6b7280", lineHeight: 1.8 }}>
          しばらく待っても表示されない場合は、下のボタンを押してください。
        </div>
        <button
          type="button"
          onClick={() => window.location.reload()}
          style={{
            padding: "10px 28px", borderRadius: 8, border: "none",
            background: "#0284c7", color: "#ffffff", fontSize: 14,
            fontWeight: 700, cursor: "pointer",
          }}
        >
          再読み込み
        </button>
      </body>
    </html>
  );
}
